window.RP_SESSION={"id":"S-75e8e522e6c7","messages":[{"id":"RP-III-0011416","time":"2026-02-03T01:41:00+09:00","room":"RP III","name":"머챈트 마이아","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"지금은 아주 약간의 어제.\n스텔라 스타라이트가 2주 간의 휴가를 마치고 돌아오지 않은 어느 밤.\n\n머챈트는 길드 밖 모닥불의 길드원들이 재잘거리는 수다를 들으며 조용히 펜과 종이를 꺼내 듭니다.","characters":["P-92738ae601c0"]},{"id":"RP-III-0011417","time":"2026-02-03T01:47:00+09:00","room":"RP III","name":"머챈트 마이아","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"https://youtu.be/mce70-bplSI?si=_48oPeYs5LOoyuuO&t=24","characters":["P-92738ae601c0"]},{"id":"RP-III-0011418","time":"2026-02-03T01:52:00+09:00","room":"RP III","name":"머챈트 마이아","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"안녕, 스텔라.\n\n네가 잠시 떠나있는 동안\n우린 여전히 지직거리는 초단파처럼\n개구진 웅성거림을 유지하고 있어.\n\n그거 알아?\n마리아는 술을 끊었어.\n물론 아직 완벽히 금주에 성공하진 못했지만, 나름 절주하고자 하는 모습을 보면 어찌나 내가 다 뿌듯한지. 늘 서투르고 틱틱거렸던 꼬맹이가, 이제보니 어엿한 숙녀가 되고 있지 뭐야? \n\n마리아도 조금 앳 된 티를 벗어난 것 같아.\n\n그리고 리스는 휴가를 보냈어.\n어디로, 왜 떠났는지 자세히 묻진 않았지만 하나 둘 자신만의 여정을 떠나는 뒷모습을 쳐다보면 문득 그런 생각이 들어.\n\n지금은 함께 웃고, 울고, 떠드는 내 옆자리의 동료들도 언젠고 자신만의 결말을 찾기 위해 떠나가지 않을까. 하는 생각.\n\n늠름한 내 친구들이 서로 웃으며 멀어지는 뒷모습을 떠올리면 막이 내려가는 무대의 피날레처럼. 그 뒤는 긴 암전이 맴돌지 않을까. 하는 그런 생각.\n\n그땐 여전히 네가 있을까?\n또, 난 여전히 여기에 있을까?\n\n다른 건 몰라도 내가 한 가지 확실","characters":["P-92738ae601c0"]},{"id":"RP-III-0011419","time":"2026-02-03T01:53:00+09:00","room":"RP III","name":"머챈트 마이아","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-92738ae601c0"]},{"id":"RP-III-0011420","time":"2026-02-03T01:53:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]},{"id":"RP-III-0011421","time":"2026-02-03T12:50:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"unresolved","type":"dialogue","body":"!결투","characters":[]},{"id":"RP-III-0011422","time":"2026-02-03T12:50:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"결투 판정\n결과 : [67] = [67]","characters":[]},{"id":"RP-III-0011423","time":"2026-02-03T12:50:00+09:00","room":"RP III","name":"브라그니르 라르손","profile":"브라그니르 라르손","identity":"unresolved","type":"dialogue","body":"!결투","characters":[]},{"id":"RP-III-0011424","time":"2026-02-03T12:50:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"결투 판정\n결과 : [66] = [66]","characters":[]}]};
